WITH matched_keys AS (SELECT id FROM orders EXCEPT DISTINCT SELECT id FROM orders WHERE status = 'SHIPPED'), kept_rows AS (SELECT s.* FROM orders s JOIN matched_keys k ON s.id = k.id) SELECT DATE_TRUNC('MONTH', order_date) AS activity_month, SUM(CASE WHEN status = 'SHIPPED' THEN amount ELSE 0 END) AS shipped_amount, APPROX_PERCENTILE(shipping_fee, ARRAY(0.25, 0.5, 0.75)) AS shipping_fee_quartiles, COUNT_IF(status = 'CANCELLED') AS cancelled_events FROM kept_rows GROUP BY DATE_TRUNC('MONTH', order_date) HAVING COUNT_IF(status = 'CANCELLED') >= 1 ORDER BY activity_month
